<script setup>
import {ref,reactive,computed,onMounted,watch} from 'vue'
import SrmModal from '../srm-ui/SrmModal.vue'
import BpmnModeler from './BpmnModeler.vue'
const props=defineProps({api:Function,context:Object,supplier:Object,categories:{type:Array,default:()=>[]}}),emit=defineEmits(['changed','inspect'])
const fields={name:'供应商名称',category:'品类',creditCode:'信用代码',bankAccount:'银行账号',bankName:'开户行',address:'注册地址'}
const kinds={ONBOARD:'准入申请',CHANGE:'关键资料变更',FREEZE:'冻结申请',UNFREEZE:'解冻申请',ELIMINATE:'淘汰申请',AWARD:'寻源定点',COL_REVIEW:'采购协同审核',QUALITY_REVIEW:'质量审核'},states={PENDING:'待审核',APPROVED:'已通过',REJECTED:'已驳回',RETURNED:'已退回补正',WITHDRAWN:'已撤回'}
const actions={CLAIM:'领取',APPROVE:'同意',REJECT:'驳回',RETURN:'退回补正',TRANSFER:'转办',ADD_SIGN:'加签',WITHDRAW:'撤回'}
const list=ref([]),tasks=ref([]),historyRows=ref([]),historyTotal=ref(0),historyPage=ref(1),historyStatus=ref(''),historyKind=ref(''),workTab=ref('tasks'),definitions=ref([]),workflowCategories=ref([]),categoryDrafts=ref({}),selected=ref(null),decisionContext=ref(null),error=ref(''),busy=ref(false),modal=ref(''),kind=ref('ONBOARD'),comment=ref(''),target=ref(''),categoryNecessity=ref(''),performanceConclusion=ref(''),candidates=ref([]),activeTask=ref(null),action=ref('APPROVE'),invitation=ref(''),versions=ref([])
const uploadKind=ref('ONBOARD'),uploadFile=ref(null)
const designerXml=ref(''),designerKind=ref('ONBOARD'),designerOpen=ref(false),designerBusy=ref(false)
const form=reactive({name:'',category:'',creditCode:'',bankAccount:'',bankName:'',address:'',reason:''})
const admin=computed(()=>!props.context.portal&&(props.context.roles.includes('superAdmin')||props.context.roles.includes('SYS-ADMIN')))
const canApply=computed(()=>props.supplier&&!['REVIEWING','ELIMINATED'].includes(props.supplier.status)&&!list.value.some(x=>x.status==='PENDING'))
async function loadHistory(){const q=new URLSearchParams({current:historyPage.value,size:20,status:historyStatus.value,kind:historyKind.value});const d=await props.api('/approvals/history?'+q);historyRows.value=d.records;historyTotal.value=d.total}
async function refreshHistory(){error.value='';try{await loadHistory()}catch(e){error.value=e.message}}
async function load(){error.value='';try{if(props.supplier){list.value=await props.api('/suppliers/'+props.supplier.id+'/approvals');versions.value=await props.api('/suppliers/'+props.supplier.id+'/versions')}else{tasks.value=await props.api('/approvals/tasks');if(workTab.value==='history')await loadHistory();if(admin.value){[definitions.value,workflowCategories.value]=await Promise.all([props.api('/workflow/definitions'),props.api('/workflow/categories')]);categoryDrafts.value=Object.fromEntries(workflowCategories.value.map(x=>[x.businessType,{categoryCode:x.categoryCode,categoryName:x.categoryName}]))}}}catch(e){error.value=e.message}}
function kindLabel(key){const mapping=workflowCategories.value.find(x=>x.businessType===key);return mapping?.categoryName||kinds[key]||key}
async function saveWorkflowCategory(row){error.value='';try{await props.api('/workflow/categories/'+row.businessType,{expectedVersion:row.rowVersion,...categoryDrafts.value[row.businessType]},'POST');await load()}catch(e){error.value=e.message}}
async function switchTab(value){workTab.value=value;historyPage.value=1;await load()}
onMounted(load);watch(()=>props.supplier?.rowVersion,load)
function apply(k){kind.value=k;modal.value='apply';error.value='';Object.assign(form,{name:props.supplier.name,category:props.supplier.category,creditCode:'',bankAccount:'',bankName:props.supplier.bankName||'',address:props.supplier.address||'',reason:''})}
async function submit(){busy.value=true;error.value='';try{let changes;if(kind.value==='CHANGE'){changes={...form,rowVersion:props.supplier.rowVersion};delete changes.reason;if(!changes.creditCode)delete changes.creditCode;if(!changes.bankAccount)delete changes.bankAccount}selected.value=await props.api('/suppliers/'+props.supplier.id+'/approvals',{kind:kind.value,requestKey:crypto.randomUUID(),rowVersion:props.supplier.rowVersion,reason:form.reason,changes},'POST');modal.value='';await load();emit('changed')}catch(e){error.value=e.message}finally{busy.value=false}}
async function withdraw(){busy.value=true;error.value='';try{selected.value=await props.api('/approvals/'+selected.value.id+'/withdraw',{comment:comment.value},'POST');modal.value='';await load();emit('changed')}catch(e){error.value=e.message}finally{busy.value=false}}
async function show(id){error.value='';decisionContext.value=null;try{selected.value=await props.api('/approvals/'+id);if(selected.value.kind==='ONBOARD'){const category=props.categories.find(c=>c.code===selected.value.supplierCategory);decisionContext.value={category:category?.name||selected.value.supplierCategory,performance:null};try{decisionContext.value.performance=await props.api('/performance/suppliers/'+encodeURIComponent(selected.value.supplierId)+'/summary?months=12')}catch{decisionContext.value.performance=null}}}catch(e){error.value=e.message}}
async function prepare(t,a){activeTask.value=t;action.value=a;comment.value='';target.value='';categoryNecessity.value='';performanceConclusion.value='';error.value='';try{if(['TRANSFER','ADD_SIGN'].includes(a))candidates.value=await props.api('/approvals/'+selected.value.id+'/tasks/'+t.id+'/candidates');modal.value='decision'}catch(e){error.value=e.message}}
async function decide(){busy.value=true;error.value='';try{selected.value=await props.api('/approvals/'+selected.value.id+'/tasks/'+activeTask.value.id,{action:action.value,comment:comment.value,targetId:target.value||null,categoryNecessity:categoryNecessity.value||null,performanceConclusion:performanceConclusion.value||null},'POST');modal.value='';await load();emit('changed')}catch(e){error.value=e.message}finally{busy.value=false}}
function myTask(t){if(props.context.portal||selected.value?.requestedBy===props.context.userId||selected.value?.status!=='PENDING')return false;return (!t.assignee||t.assignee===props.context.userId)&&(props.context.roles.includes('superAdmin')||props.context.roles.includes(t.node==='sqe'?'SQE':'CAT-MGR')||t.node==='ADD_SIGN'&&t.assignee===props.context.userId)}
async function publish(k){try{await props.api('/workflow/definitions',{kind:k},'POST');await load()}catch(e){error.value=e.message}}
async function upload(){try{if(!uploadFile.value)throw new Error('请选择BPMN文件');const data=new FormData();data.append('kind',uploadKind.value);data.append('file',uploadFile.value);await props.api('/workflow/definitions/upload',data,'POST');await load()}catch(e){error.value=e.message}}
async function openDesigner(d){error.value='';try{const blob=await props.api('/workflow/definitions/'+d.id+'/xml',undefined,'GET',true);designerXml.value=await blob.text();designerKind.value=d.businessType||d.key.replace(/^srm_/,'').toUpperCase();designerOpen.value=true}catch(e){error.value=e.message}}
async function publishDesigned(xml){designerBusy.value=true;error.value='';try{const file=new File([xml],`srm-${designerKind.value}.bpmn20.xml`,{type:'application/xml'}),data=new FormData();data.append('kind',designerKind.value);data.append('file',file);await props.api('/workflow/definitions/upload',data,'POST');designerOpen.value=false;await load()}catch(e){error.value=e.message}finally{designerBusy.value=false}}
async function exportXml(d){try{const blob=await props.api('/workflow/definitions/'+d.id+'/xml',undefined,'GET',true),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=d.key+'.bpmn20.xml';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){error.value=e.message}}
async function suspend(d){try{await props.api('/workflow/definitions/'+d.id+'/suspension',{suspended:!d.suspended},'POST');await load()}catch(e){error.value=e.message}}
async function invite(){try{const r=await props.api('/registration-invitations',{},'POST');invitation.value=r.invitation}catch(e){error.value=e.message}}
</script>
<template>
 <section class="lifecycle-panel">
  <p v-if="error&&!modal" class="form-error" role="alert">{{error}}</p>
  <template v-if="supplier">
   <div class="inline-actions" v-if="canApply"><button v-if="context.canManage&&['POTENTIAL','CORRECTION'].includes(supplier.status)" class="btn primary" @click="apply('ONBOARD')">提交准入</button><button v-if="context.canManage&&['QUALIFIED','FROZEN'].includes(supplier.status)" class="btn" @click="apply('CHANGE')">申请关键资料变更</button><button v-if="context.canClassify&&supplier.status==='QUALIFIED'" class="btn" @click="apply('FREEZE')">申请冻结</button><button v-if="context.canClassify&&supplier.status==='FROZEN'" class="btn" @click="apply('UNFREEZE')">申请解冻</button><button v-if="context.canClassify" class="btn" @click="apply('ELIMINATE')">申请淘汰</button></div>
   <div class="info-note">{{supplier.status==='CORRECTION'?'请按审核意见补齐资料后重新提交，流程从 SQE 节点重新开始。':'提交后档案和资质暂时锁定，防止审批依据发生变化。'}} 申请人与审批人分离。</div>
   <h3>审批与生命周期</h3><article v-for="l in list" :key="l.id" class="history-item"><button class="text-btn" @click="show(l.id)">{{kinds[l.kind]}} · {{states[l.status]}}</button><p>{{l.createdAt}}</p></article><p v-if="!list.length" class="muted">暂无审批申请</p>
   <h3 v-if="versions.length">资料版本追溯</h3><details v-for="v in versions" :key="v.version" class="history-item"><summary>版本 {{v.version}} · {{v.time}}</summary><table v-if="context.sensitive"><thead><tr><th>字段</th><th>变更前</th><th>变更后</th></tr></thead><tbody><tr v-for="(label,key) in fields" :key="key"><td>{{label}}</td><td>{{v.before[key]||'未填写'}}</td><td>{{v.after[key]||'未填写'}}</td></tr></tbody></table><p v-else class="muted">没有敏感字段查看权限</p></details>
  </template>
  <template v-else>
   <div class="panel-heading"><div><h2>{{workTab==='tasks'?'我的审批待办':'已办 / 审批历史'}}</h2><p>{{workTab==='tasks'?'按组织、角色、数据范围与任务归属筛选；不可审批本人申请。':'仅显示本人申请、本人经办或流程管理员可查看范围内的已结束流程。'}}</p></div><button class="btn" @click="load">刷新</button></div>
   <div class="inline-actions approval-history-tabs"><button :class="['btn',{primary:workTab==='tasks'}]" @click="switchTab('tasks')">待我处理</button><button :class="['btn',{primary:workTab==='history'}]" @click="switchTab('history')">已办 / 审批历史</button></div>
   <template v-if="workTab==='tasks'"><div class="table-scroll"><table><thead><tr><th>供应商</th><th>业务类型</th><th>审批节点</th><th>创建时间</th><th>操作</th></tr></thead><tbody><tr v-for="t in tasks" :key="t.id"><td>{{t.supplierName}}<small style="display:block">{{t.supplierCode}}</small></td><td>{{kinds[t.kind]}}</td><td>{{t.name}}</td><td>{{t.createdAt}}</td><td><button class="text-btn" @click="show(t.approvalId)">查看并处理</button></td></tr></tbody></table><div v-if="!tasks.length" class="empty-state">当前没有需要你处理的审批</div></div></template>
   <template v-else><div class="table-toolbar"><select aria-label="筛选审批状态" v-model="historyStatus" @change="historyPage=1;refreshHistory()"><option value="">全部已结束状态</option><option value="APPROVED">已通过</option><option value="REJECTED">已驳回</option><option value="RETURNED">已退回补正</option><option value="WITHDRAWN">已撤回</option></select><select aria-label="筛选业务类型" v-model="historyKind" @change="historyPage=1;refreshHistory()"><option value="">全部业务类型</option><option v-for="(label,key) in kinds" :key="key" :value="key">{{label}}</option></select></div><div class="table-scroll"><table><thead><tr><th>供应商</th><th>业务类型</th><th>结果</th><th>发起时间</th><th>结束时间</th><th>操作</th></tr></thead><tbody><tr v-for="r in historyRows" :key="r.id"><td>{{r.supplierName}}</td><td>{{kinds[r.kind]||r.kind}}</td><td>{{states[r.status]||r.status}}</td><td>{{r.createdAt}}</td><td>{{r.completedAt||'—'}}</td><td><button class="text-btn" @click="show(r.id)">查看全链路</button></td></tr></tbody></table><div v-if="!historyRows.length" class="empty-state">当前范围没有可查看的已结束审批</div><div class="table-footer"><span>共 {{historyTotal}} 项</span><button :disabled="historyPage<=1" @click="historyPage--;refreshHistory()">上一页</button><span>{{historyPage}}</span><button :disabled="historyPage*20>=historyTotal" @click="historyPage++;refreshHistory()">下一页</button></div></div></template>
   <div v-if="context.canManage" class="panel-heading"><div><h3>邀请供应商注册</h3><p>单次邀请，7天有效，注册档案归属你的组织。</p><p v-if="invitation" class="invitation-result">{{invitation}}</p></div><button class="btn" @click="invite">生成注册邀请</button></div>
   <template v-if="admin"><div class="panel-heading"><h3>流程版本与分类</h3><p>挂起版本停止新发起，已有申请继续处理。分类与 SRM 业务类型一一对应。</p></div><h4>维护业务分类映射</h4><p class="info-note">业务类型是系统固定流程标识；可维护分类编码和名称。每个业务类型唯一对应一个分类，分类编码和名称也不能重复。</p><div class="table-scroll"><table><thead><tr><th>业务类型</th><th>分类编码</th><th>分类名称</th><th>操作</th></tr></thead><tbody><tr v-for="row in workflowCategories" :key="row.businessType"><td>{{kinds[row.businessType]}} <small>({{row.businessType}})</small></td><td><input v-model="categoryDrafts[row.businessType].categoryCode" maxlength="40" pattern="[A-Z][A-Z0-9_-]{1,39}" :aria-label="row.businessType+'分类编码'" /></td><td><input v-model="categoryDrafts[row.businessType].categoryName" maxlength="80" required :aria-label="row.businessType+'分类名称'" /></td><td><button class="btn" @click="saveWorkflowCategory(row)">保存映射</button></td></tr></tbody></table></div><h4>流程版本</h4><div class="inline-actions"><button v-for="(label,k) in kinds" :key="k" class="btn" @click="publish(k)">发布{{kindLabel(k)}}新版本</button></div><table><thead><tr><th>流程分类</th><th>流程键</th><th>版本</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="d in definitions" :key="d.id"><td>{{d.categoryName||kindLabel(d.businessType)}}</td><td>{{d.key}}</td><td>v{{d.version}}</td><td>{{d.suspended?'已挂起':'可发起'}}</td><td><button class="text-btn" @click="openDesigner(d)">图形设计</button><button class="text-btn" @click="exportXml(d)">下载 BPMN</button><button class="text-btn" @click="suspend(d)">{{d.suspended?'激活':'挂起'}}</button></td></tr></tbody></table><form class="inline-actions" @submit.prevent="upload"><select aria-label="上传流程分类" v-model="uploadKind"><option v-for="(label,k) in kinds" :key="k" :value="k">{{kindLabel(k)}}</option></select><input aria-label="BPMN文件" type="file" accept=".xml,.bpmn" required @change="uploadFile=$event.target.files[0]" /><button class="btn">上传并发布版本</button></form><p class="info-note">图形设计可调整节点位置与名称；审批节点、候选角色及业务顺序受控。保存后服务端重新验证并发布新版本，旧流程实例继续使用原版本。</p></template>
  </template>
  <SrmModal v-if="selected&&!modal" :title="kinds[selected.kind]+' · '+states[selected.status]" @close="selected=null"><h3>{{selected.supplierName}}</h3><button class="text-btn" @click="emit('inspect',selected.supplierId);selected=null">查看供应商档案与资质</button><p>申请人 {{selected.requestedBy}}</p><button v-if="selected.status==='PENDING'&&(selected.requestedBy===context.userId||context.roles.includes('superAdmin'))" class="btn" @click="modal='withdraw';comment=''">撤回申请</button><p>申请原因：{{selected.reason||'首次准入'}}</p><details v-if="selected.kind==='CHANGE'"><summary>查看拟变更资料与原始资料</summary><table v-if="context.sensitive"><thead><tr><th>字段</th><th>当前有效资料</th><th>申请变更为</th></tr></thead><tbody><tr v-for="(label,key) in fields" :key="key"><td>{{label}}</td><td>{{selected.before[key]||'未填写'}}</td><td>{{selected.changes[key]??'保持原值'}}</td></tr></tbody></table><p v-else>没有敏感字段查看权限</p></details><section v-if="selected.history?.length" class="approval-timeline"><h3>流程节点历史</h3><ol><li v-for="h in selected.history" :key="h.id"><strong>{{h.name}}</strong><span>审批人：{{h.assignee||'未分配'}}</span><small>{{h.start||'—'}} — {{h.end||'进行中'}}</small><small v-if="h.deleteReason">流程结果：{{h.deleteReason}}</small></li></ol></section><article v-for="a in selected.actions" :key="a.id" class="history-item"><strong>{{actions[a.action]||a.action}} · {{a.actorId}}</strong><p>{{a.comment}}</p><small>{{a.time}}</small></article><article v-for="t in selected.tasks" :key="t.id" class="history-item"><h3>{{t.name}}</h3><p>{{t.assignee?'已分配审批人':'等待角色候选人处理'}}</p><div v-if="myTask(t)" class="inline-actions"><button class="btn primary" @click="prepare(t,'APPROVE')">同意</button><button class="btn" @click="prepare(t,'REJECT')">驳回</button><button v-if="t.node==='sqe'&&selected.kind==='ONBOARD'" class="btn" @click="prepare(t,'RETURN')">退回补正</button><template v-if="t.node!=='ADD_SIGN'"><button class="btn" @click="prepare(t,'CLAIM')">领取</button><button class="btn" @click="prepare(t,'TRANSFER')">转办</button><button class="btn" @click="prepare(t,'ADD_SIGN')">加签</button></template></div></article><p v-if="error" class="form-error">{{error}}</p></SrmModal>
  <SrmModal v-if="modal==='apply'" :title="kinds[kind]" @close="modal=''"><form @submit.prevent="submit"><template v-if="kind==='CHANGE'"><label>供应商名称<input v-model="form.name" required maxlength="128" /></label><label>品类<select v-model="form.category"><option v-for="c in categories" :key="c.code" :value="c.code">{{c.name}}</option></select></label><label>信用代码（留空保持原值）<input aria-label="变更信用代码" v-model="form.creditCode" maxlength="18" /></label><label>银行账号（留空保持原值）<input aria-label="变更银行账号" v-model="form.bankAccount" maxlength="64" /></label><label>开户行<input v-model="form.bankName" maxlength="64" /></label><label>地址<input v-model="form.address" maxlength="255" /></label></template><label>申请原因<textarea aria-label="申请原因" v-model="form.reason" :required="kind!=='ONBOARD'" maxlength="1000" /></label><div class="info-note">{{kind==='ONBOARD'?'提交前校验品类要求的全部有效资质及管理员联系人。':'审批通过后生效，审批期间保留原始有效资料及状态。'}}</div><p v-if="error" class="form-error" role="alert">{{error}}</p><div class="modal-actions"><button class="btn primary" :disabled="busy">确认提交</button></div></form></SrmModal>
  <SrmModal v-if="modal==='withdraw'" title="撤回申请" @close="modal=''"><form @submit.prevent="withdraw"><label>撤回原因<textarea aria-label="撤回原因" v-model="comment" required maxlength="1000" /></label><p v-if="error" class="form-error">{{error}}</p><div class="modal-actions"><button class="btn primary" :disabled="busy">确认撤回</button></div></form></SrmModal>
  <SrmModal v-if="modal==='decision'" :title="actions[action]" @close="modal=''"><form @submit.prevent="decide"><template v-if="selected.kind==='ONBOARD'&&activeTask?.node==='manager'&&['APPROVE','REJECT'].includes(action)"><article class="info-note"><strong>准入评估依据</strong><p>申请品类：{{decisionContext?.category||'读取中'}}</p><template v-if="decisionContext?.performance"><p>近12个月有效绩效 {{decisionContext.performance.validMonths}} 期；平均总分 {{decisionContext.performance.averageTotal??'暂无'}}；{{decisionContext.performance.insufficientHistory?'绩效历史不完整':'绩效历史完整'}}。</p><p v-if="decisionContext.performance.missingPeriods?.length">缺失月份：{{decisionContext.performance.missingPeriods.join('、')}}</p></template><p v-else>未取得近12个月绩效汇总；请在审批意见中记录采用的绩效判断依据或说明无历史。</p></article><label>品类必要性<select aria-label="品类必要性" v-model="categoryNecessity" required><option value="">请选择</option><option value="REQUIRED">必要</option><option value="NOT_REQUIRED">非必要</option></select></label><label>绩效评估结论<select aria-label="绩效评估结论" v-model="performanceConclusion" required><option value="">请选择</option><option value="ACCEPT">通过</option><option value="CONDITIONAL">有条件通过</option><option value="REJECT">不通过</option></select></label><p class="info-note">该结论会随审批意见加密留档；驳回时绩效结论必须选择“不通过”。</p></template><label v-if="['TRANSFER','ADD_SIGN'].includes(action)">接收人<select aria-label="接收人" v-model="target" required><option value="">请选择有权处理本任务的审批人</option><option v-for="c in candidates" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>审批意见<textarea aria-label="审批意见" v-model="comment" required maxlength="1000" placeholder="请填写业务意见，避免填写完整银行账号等敏感信息" /></label><p v-if="error" class="form-error" role="alert">{{error}}</p><div class="modal-actions"><button class="btn primary" :disabled="busy">确认{{actions[action]}}</button></div></form></SrmModal>
  <BpmnModeler v-if="designerOpen" :xml="designerXml" :busy="designerBusy" @save="publishDesigned" @close="designerOpen=false" />
 </section>
</template>
<style scoped>
pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;max-height:230px;overflow:auto;background:#f6f8f6;padding:12px;border-radius:8px}textarea{min-height:88px;resize:vertical;padding:10px;border:1px solid #dce4df;border-radius:8px;font:inherit;width:100%;box-sizing:border-box}.invitation-result{overflow-wrap:anywhere;user-select:all;font-family:monospace}.lifecycle-panel h3{margin-top:20px}.approval-history-tabs{margin:10px 0 16px}.approval-timeline{border:1px solid #dce7e0;border-radius:10px;padding:12px;margin:16px 0}.approval-timeline ol{padding-left:22px}.approval-timeline li{padding:7px 0}.approval-timeline li span,.approval-timeline li small{display:block;color:#6d7c73;margin-top:3px}
</style>
